// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 contributionCount, uint256 blockNumberSeed) public {
        vm.assume(contributionCount > 0 && contributionCount <= 20);
        vm.assume(blockNumberSeed < type(uint256).max / 2);

        // warp to a future time so block.timestamp > pastBlockTime initially
        vm.warp(1);

        uint256 expectedBalance = 0;
        uint256 outputBlockNumber = blockNumberSeed;

        vm.deal(address(this), 10 ether * contributionCount);

        for (uint256 i = 0; i < contributionCount; i++) {
            uint256 bn = outputBlockNumber + i;
            vm.roll(bn);
            vm.warp(block.timestamp + 1);
            vm.prank(address(this));
            (bool ok,) = address(c).call{value: 10 ether}("");
            require(ok, "call failed");
            expectedBalance += 10 ether;
            if (bn % 15 == 0) {
                expectedBalance = 0;
            }
        }

        assertTrue(address(c).balance == expectedBalance);
    }
}

