pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address actor, uint256 firstBlockTimestamp, uint256 secondBlockTimestamp, uint256 blockNumber) public {
        vm.assume(firstBlockTimestamp > 0);
        vm.assume(secondBlockTimestamp >= firstBlockTimestamp);
        vm.assume(blockNumber >= 1);
        vm.assume(actor != address(this));
        vm.assume(actor != address(c));

        // fund actor
        vm.deal(actor, 20 ether);

        // first call: set pastBlockTime to firstBlockTimestamp
        vm.warp(firstBlockTimestamp);
        vm.roll(blockNumber);
        vm.prank(actor);
        c.f{value: 10 ether}();

        // second call: attempt with >= (mutant) vs > (original) check
        vm.warp(secondBlockTimestamp);
        vm.roll(blockNumber);
        vm.prank(actor);
        (bool success2, ) = address(c).call{value: 10 ether}("");

        // Assert: if second call succeeded, pastBlockTime must be strictly greater than firstBlockTimestamp
        // The correct contract guarantees pastBlockTime > firstBlockTimestamp after two successful calls;
        // the mutant allows pastBlockTime == firstBlockTimestamp (when firstBlockTimestamp == secondBlockTimestamp)
        assertTrue(!success2 || c.pastBlockTime() > firstBlockTimestamp);
    }
}

