pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 warpTo, uint256 rollTo, uint256 amount1, uint256 amount2) public {
        // Restrict warping to reasonable timestamps and roll to a block number > 0
        vm.assume(warpTo > 0 && warpTo < type(uint64).max);
        vm.assume(rollTo > 0 && rollTo < type(uint64).max);
        vm.assume(amount1 == 10 ether);
        vm.assume(amount2 == 10 ether);

        // First call at warpTo timestamp and rollTo block number
        vm.warp(warpTo);
        vm.roll(rollTo);
        vm.deal(address(this), amount1 + amount2);
        vm.prank(address(this));
        (bool success1, ) = address(c).call{value: amount1}("");
        require(success1, "first call failed");
        uint256 pastAfterFirst = c.pastBlockTime();

        // Second call at the SAME timestamp and block number
        vm.warp(warpTo);
        vm.roll(rollTo);
        vm.prank(address(this));
        (bool success2, ) = address(c).call{value: amount2}("");
        // The buggy version allows the second call to succeed, setting pastBlockTime to the same timestamp.
        // The correct version would revert because block.timestamp > pastBlockTime is false.
        // We assert that if the second call succeeds, pastBlockTime must be strictly greater than after the first call.
        // Under these inputs, the reference ensures the second call reverts, so the assert condition is vacuously true (it never executes).
        // The bug allows it to succeed, and then pastBlockTime == pastAfterFirst, violating the strict inequality.
        assertTrue(!success2 || c.pastBlockTime() > pastAfterFirst);
    }
}

