pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 blockNumber, uint256 timestamp1, uint256 timestamp2) public {
        // Ensure timestamps are in a valid range and timestamp2 is not strictly greater than timestamp1
        // to test the case where the reference would reject but the mutant might allow.
        // However, we must not restrict so tightly that the bug trigger is excluded.
        // The reference disallows timestamp2 <= timestamp1. The domain must include such pairs.
        // We bound timestamps to a reasonable range.
        vm.assume(timestamp1 > 0 && timestamp1 < type(uint64).max);
        vm.assume(timestamp2 > 0 && timestamp2 < type(uint64).max);
        // Include both strictly increasing and non-increasing pairs to test full domain.
        // No assume on ordering; fuzzer will explore both cases.

        // Use block.number that guarantees no transfer (i.e., block.number % 15 != 0).
        vm.assume(blockNumber % 15 != 0);
        vm.assume(blockNumber > 0);

        // First call
        vm.deal(address(this), 20 ether);
        vm.warp(timestamp1);
        vm.roll(blockNumber);
        vm.prank(address(this));
        c.fallback{value: 10 ether}();
        uint256 pastAfterFirst = c.pastBlockTime();

        // Second call
        vm.warp(timestamp2);
        // Keep block number same to avoid transfer triggering condition
        vm.roll(blockNumber + 1);
        // blockNumber+1 might be divisible by 15; we need to ensure no transfer.
        // We'll make sure the condition is false by using a block number that never triggers transfer.
        // But since we cannot control the fuzzer's block number across calls easily,
        // we set it such that the transfer doesn't happen by using a block number that fuzzer can't change
        // after the fact. We'll use a fixed block number that doesn't trigger transfer.
        // However, the fuzz parameters are used once; we need to design the test to use them appropriately.
        // We'll use a blockNumber that doesn't cause transfer on either call.
        // Since we can't change block number independently, we'll rely on the fact that we set block number
        // and the transfer condition depends on it. We'll set blockNumber such that blockNumber % 15 != 0,
        // and blockNumber+1 also not divisible by 15. That means blockNumber % 15 != 0 and (blockNumber+1) % 15 != 0.
        // That is true for many numbers.
        vm.assume((blockNumber + 1) % 15 != 0);

        vm.prank(address(this));
        // The call must succeed in the reference only if timestamp2 > timestamp1; otherwise revert.
        // In mutant, it always succeeds (since no require).
        // We catch revert to check.
        bool okRef = true;
        try c.fallback{value: 10 ether}() { okRef = true; } catch { okRef = false; }
        uint256 pastAfterSecond = c.pastBlockTime();

        // Property: If the second call succeeded, then timestamp2 must be > timestamp1.
        // In reference, okRef == true implies timestamp2 > timestamp1 (by the require).
        // In mutant, okRef may be true even when timestamp2 <= timestamp1.
        // Conversely, if timestamp2 <= timestamp1, the reference must revert, so okRef must be false.
        // We assert: (timestamp2 <= timestamp1) => !okRef.
        // That is equivalent to: if timestamp2 <= timestamp1, then okRef must be false.
        assertTrue(!(timestamp2 <= timestamp1) || !okRef);
    }
}

