contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 blockNum, uint256 warpTime) public {
        // Restrict to admissible domain: positive future timestamp, block number > 0, and pastBlockTime initially 0 so warpTime > 0.
        vm.assume(blockNum > 0);
        vm.assume(warpTime > 0);
        vm.roll(blockNum);
        vm.warp(warpTime);
        address sender = makeAddr("sender");
        vm.deal(sender, 10 ether);
        vm.prank(sender);
        // The fallback function requires exactly 10 ether, and the reference always clears the balance only if block.number % 15 == 0.
        // So the general rule: if block.number is not a multiple of 15, the contract's balance after the call must be > 0.
        try c.fallback{value: 10 ether}() {
            if (blockNum % 15 != 0) {
                assertTrue(address(c).balance > 0);
            } else {
                assertTrue(address(c).balance == 0);
            }
        } catch {
            // If the call reverts, we don't test the property; just succeed.
        }
    }
}

