import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 blockNum, uint256 blockTime) public {
        // Admissible domain: block.timestamp > 0 (pastBlockTime starts at 0)
        vm.assume(blockTime > 0);
        // The fallback requires msg.value == 10 ether; fuzz the block conditions, not the value
        vm.deal(address(this), 10 ether);
        vm.roll(blockNum);
        vm.warp(blockTime);
        // A single call to fallback
        c.fallback{value: 10 ether}();
        // After the call, if block.number % 15 == 0, the contract transfers its entire balance.
        // In the reference, the condition is % 15 == 0; in the mutant it is % 15 == 1.
        // Therefore, the resulting balance of c after the call depends on whether the condition matched.
        // The invariant: the contract balance is either 0 (when transfer triggered) or 10 ether (when not).
        // The mutant violates this for some block numbers.
        bool balanceIsZeroOr10 = (address(c).balance == 0 || address(c).balance == 10 ether);
        assertTrue(balanceIsZeroOr10);
    }
}

