contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 timestamp1, uint256 timestamp2, uint256 blockNumber2, uint8 pad) public {
        // Admissible domain: forward timestamps, second after first
        vm.assume(timestamp1 < timestamp2);
        vm.assume(blockNumber2 > 0);
        // Force the second call's block.number to be divisible by 15
        // blockNumber2 is fuzzed; we'll set block.number = blockNumber2 * 15
