        vm.roll(triggerBlock);
        vm.deal(user, 10 ether);
        vm.prank(user);
        c.fallback{value: 10 ether}();

        // After a triggered transfer, reference contract balance is zero; buggy version retains balance.
        assertEq(address(c).balance, 0, "Balance must be zero after triggered transfer");
    }
