pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 blockNum, uint256 warpTime, uint256 waitSeconds) public {
        // Restrict to admissible domain: block number > 0, warpTime large enough, waitSeconds > 0
        vm.assume(blockNum > 0);
        vm.assume(warpTime > 0);
        vm.assume(waitSeconds > 0 && waitSeconds < 365 days);

        // Set block number and timestamp for first call
        vm.roll(blockNum);
        vm.warp(warpTime);

        // Fund an EOA and make the first fallback call
        address actor = address(0x1234);
        vm.deal(actor, 100 ether);
        vm.prank(actor);
        c.fallback{value: 10 ether}();

        // Record pastBlockTime after first successful call
        uint256 firstPastBlockTime = c.pastBlockTime();

        // Advance time for second call
        vm.warp(warpTime + waitSeconds);
        vm.roll(blockNum + 1);

        // Second call attempt
        vm.prank(actor);
        bool ok;
        try c.fallback{value: 10 ether}() { ok = true; } catch { ok = false; }

        // If second call succeeded (ok == true), pastBlockTime must be strictly greater than before
        // For the reference, this always holds; for the buggy mutant, the second call always reverts,
        // so ok == false, but the invariant only requires the implication when ok is true.
        // However, the mutant cannot have any successful second call, meaning the invariant
        // "pastBlockTime strictly increased after a second successful call" is vacuously true.
        // We need a property that the reference satisfies and the mutant violates.
        // The reference allows two consecutive successful calls if block.number % 15 != 0.
        // The mutant prevents the second call entirely, so the property "it is possible to have
        // two successful fallback calls with pastBlockTime increasing" distinguishes them.
        // We can check: after a successful first call, a second call with block.number % 15 != 0
        // succeeds (reference) vs fails (mutant).
        vm.assume(blockNum % 15 != 0 && (blockNum + 1) % 15 != 0);
        // For the reference, second call succeeds and pastBlockTime advances.
        // For the mutant, second call reverts.
        assertTrue(ok && c.pastBlockTime() > firstPastBlockTime);
    }
}

